import numpy as np
import pandas as pd

def market_regime_ok(nifty_close, window=200, slope_window=60, max_slope=0.05):
    nifty_ma = nifty_close.rolling(window).mean()
    slope = nifty_ma.pct_change(slope_window).iloc[-1]
    return abs(slope) < max_slope


def structural_break_ok(close, ma_window=20, phi_window=60, alert_threshold=0.97):
    ma = close.rolling(ma_window).mean()
    deviation = (close - ma).dropna().iloc[-phi_window:]
    x = deviation.shift(1).dropna()
    y = deviation.loc[x.index]
    phi = np.polyfit(x, y, 1)[0]
    return phi < alert_threshold


def build_watchlist(universe, nifty_close, recent_failures,
                     z_thresh=-2, hl_cap=10, max_ma_slope=0.03,
                     rsi_thresh=35, max_recent_failures=2):
    if not market_regime_ok(nifty_close):
        return pd.DataFrame()  # step aside entirely in a trending market

    candidates = []
    for ticker, close in universe.items():
        if recent_failures.get(ticker, 0) >= max_recent_failures:
            continue  # this name has failed reversion too often lately
        if not structural_break_ok(close):
            continue  # phi has drifted toward a random walk

        signals, half_life = compute_signals(close)  # Chapter 7's pipeline
        row = signals.iloc[-1]

        if pd.isna(half_life) or half_life >= hl_cap:
            continue
        if abs(row["ma_slope"]) >= max_ma_slope:
            continue
        if row["z"] >= z_thresh:
            continue
        if row["rsi"] >= rsi_thresh:
            continue

        candidates.append({"ticker": ticker, "z": round(row["z"], 2),
                            "half_life": round(half_life, 1), "rsi": round(row["rsi"], 1)})

    # A shortlist for human review, not an automatic trade list.
    return pd.DataFrame(candidates).sort_values("z") if candidates else pd.DataFrame()
